
// === resources/js/constants.js ===
// Application Constants - Centralized configuration

const AppConstants = {
    // File handling
    FILE: {
        FILENAME_LENGTH: 6,
        MAX_SIZE_MB: 10,
        VALID_IMAGE_TYPES: ['image/jpeg', 'image/png', 'image/webp', 'image/svg+xml']
    },

    // UI Configuration
    UI: {
        ALERT_DURATION: 3000,
        ALERT_FADE_SPEED: 300,
        MAX_ALERTS: 3,
        WIZARD_TOTAL_STEPS: 4
    },

    // Canvas Configuration
    CANVAS: {
        SCALE_MAX_MULTIPLIER: 0.002,
        SNAP_ZONE_RATIO: 20, // canvas.width / 20
        TARGET_FIND_TOLERANCE: 15,
        CORNER_SIZE_MULTIPLIER: 0.03,
        BORDER_SCALE_FACTOR: 2,
        PADDING: 4,
        ROTATION_SNAP_TOLERANCE: 2, // degrees
        ROTATION_SNAP_ANGLES: [0, 90, 180, 270]
    },

    // Export Configuration
    EXPORT: {
        DEFAULT_DPI: 200,
        SCREEN_DPI: 72,
        MAX_PIXELS: 250000000, // 250MP browser limit
        QR_MIN_SIZE: 512,
        QR_MAX_SIZE: 2048,
        QR_BORDER_PERCENT: 0.05
    },

    // Element Scaling
    SCALING: {
        TEXT_DEFAULT_WIDTH_RATIO: 0.8,
        TEXT_DEFAULT_HEIGHT_RATIO: 0.5,
        IMAGE_DEFAULT_WIDTH_RATIO: 0.5,
        IMAGE_DEFAULT_HEIGHT_RATIO: 0.4,
        QR_DEFAULT_WIDTH_RATIO: 0.25,
        QR_DEFAULT_HEIGHT_RATIO: 0.25,
        CIRCLE_DEFAULT_WIDTH_RATIO: 0.3,
        CIRCLE_DEFAULT_HEIGHT_RATIO: 0.3,
        CROSS_DEFAULT_WIDTH_RATIO: 0.4,
        CROSS_DEFAULT_HEIGHT_RATIO: 0.3
    },

    // Circle Clip Sizes
    CIRCLE_SIZES: {
        LARGE: { value: 2, percentage: 0.9 },
        MEDIUM: { value: 3, percentage: 0.7 },
        SMALL: { value: 4, percentage: 0.5 }
    },

    // Canvas colors. These are hex/css literals because they are applied to
    // fabric.js canvas objects, which do not resolve CSS custom properties.
    // The brand colors are kept in sync with the Gruene-AT design-system tokens:
    //   var(--gat-color-primary) = #257639  -> BACKGROUND_*, LOGO_TEXT
    //   var(--gat-color-magenta) = #E6007E  -> PINK_CIRCLE
    // (CORNER_COLOR / BORDER_COLOR are fabric.js selection-handle colors,
    //  not part of the rendered output, and are intentionally left unchanged.)
    // If the DS palette changes, update these constants in lockstep.
    COLORS: {
        BACKGROUND_PRIMARY: "#257639",
        BACKGROUND_SECONDARY: "#257639",
        PINK_CIRCLE: "#E6007E",
        LOGO_TEXT: "#257639",
        // Region name on the logo bar is a transparent KNOCKOUT, not a fill.
        // It is rendered with globalCompositeOperation 'destination-out', so the
        // colour is immaterial (only the glyph alpha erases the white bar). Kept
        // opaque white for a crisp erase. LOGO_TEXT is retained for reference/back-compat.
        LOGO_KNOCKOUT: "#ffffff",
        TEXT_STROKE: "#000000",
        CORNER_COLOR: "yellow",
        BORDER_COLOR: "rgba(88,42,114)",
        CORNER_STROKE: "#000000"
    },

    // Font Configuration
    FONTS: {
        FAMILY: "Gotham Narrow",
        DEFAULT_LOGO: "Gotham Narrow",
        DEFAULT_TEXT: "Gotham Narrow",
        // Gotham Narrow ships as four separate faces, registered under one
        // family in input.css. Only these three weights exist — 500/600/800
        // would silently snap to a neighbour.
        WEIGHT_TEXT: 900,    // default canvas text (Ultra)
        WEIGHT_LOGO: 700,    // logo overlay text (Bold)
        WEIGHT_BOOK: 400,    // body / book equivalent (Book)
        // Manual tracking for fabric.js text (charSpacing, 1/1000 em).
        // 0 = Gotham Narrow's own metrics. The -30 ("-3") tracking existed
        // only to make the wider Raleway approximate Gotham's set width;
        // with the real font it would over-tighten.
        CHAR_SPACING: 0,
        // User-selectable text fonts, labelled DESCRIPTIVELY (type + use),
        // never by brand name. Option ids match #font-style-select values.
        OPTIONS: [
            { id: 'standard', label: 'Standardschrift — Headlines & Fließtext', family: 'Gotham Narrow', weight: 900, style: 'normal' },
            { id: 'accent',   label: 'Betonte Serifenschrift — für Zitate & Akzente', family: 'Vollkorn', weight: 900, style: 'italic' }
        ],
        // Each entry carries its own family so the preload observer binds to
        // the correct font. Mixing families under a single observer family
        // would leave the other font unloaded (serif fallback on first use).
        PRELOAD_FONTS: [
            { family: 'Gotham Narrow', weight: 900, style: 'italic' },  // italic accent
            { family: 'Gotham Narrow', weight: 900 },                   // default text
            { family: 'Gotham Narrow', weight: 400 },                   // book / body
            { family: 'Gotham Narrow', weight: 700 },                   // default logo
            { family: 'Vollkorn', weight: 900, style: 'italic' },              // accent serif (Black Italic)
            { family: 'Vollkorn', weight: 400 }                                // accent serif (book)
        ]
    },

    // Logo Configuration
    LOGO: {
        TEXT_SCALE_LONG: 4.8,
        TEXT_SCALE_SHORT: 6,
        MAX_TEXT_LENGTH: 16,
        LINE_HEIGHT: 0.8,
        ANGLE: -5.0,  // matches the logo bar's actual slope (white bar edges measured at -5.0°); keeps the region name parallel to the bar
        WIDTH_SCALE: 0.95,
        // Bar text positioning - use WIDTH as reference since it's constant
        BAR_OFFSET_FROM_TOP: 0.90, // Single-line text starts at 90% of logo WIDTH from logo top
        BAR_OFFSET_FROM_TOP_LONG: 0.89, // Two-line text starts slightly higher to fit within the taller bar
        // Automatic positioning configuration
        BORDERLESS_MARGIN_PERCENT: 0.02, // For borderless templates: logo bottom margin as percentage of canvas height (2%)
        // Two artworks of the same logo. The "blanko" files are pure white on
        // transparent: over the green canvas the enclosed areas — the counters
        // of the G, the letters in the white bar — show the green through, and
        // that is how the logo is meant to read. Over a background photograph
        // they show the PHOTO, and the wordmark becomes unreadable.
        //
        // The "gruen" files have exactly those enclosed areas filled with the
        // brand green; the outer transparency is untouched, so the logo still
        // has no box around it. Generated by scripts/make-green-logo.py.
        FILES: {
            LONG: "Logo-zweizeilig_blanko.png",
            SHORT: "Logo-einzeilig_blanko.png",
            LONG_FILLED: "Logo-zweizeilig_gruen.png",
            SHORT_FILLED: "Logo-einzeilig_gruen.png"
        }
    }
};

