// === resources/js/validation.js ===
// Validation Utilities - Centralized validation functions

const ValidationUtils = {
    // File validation
    VALID_IMAGE_TYPES: ['image/jpeg', 'image/png', 'image/webp', 'image/svg+xml'],
    
    isValidImage(fileType) {
        return this.VALID_IMAGE_TYPES.includes(fileType);
    },

    isValidImageFile(file) {
        if (!file) return false;
        return this.isValidImage(file.type);
    },

    // JSON validation
    isValidJSON(str) {
        try {
            JSON.parse(str);
            return true;
        } catch (e) {
            return false;
        }
    },

    // Canvas validation
    validateStep1() {
        const template = jQuery('#canvas-template').val();
        const logo = jQuery('#logo-selection').val();
        const logoEnabled = LogoState.isLogoEnabled();

        const errors = [];

        if (!template) {
            errors.push('Bitte wählen Sie eine Vorlage aus.');
        }

        // Only validate logo if logo feature is enabled
        if (logoEnabled && !logo) {
            errors.push('Bitte wählen Sie ein Logo aus.');
        }

        return {
            isValid: errors.length === 0,
            errors: errors
        };
    },

    // Text validation
    validateTextInput(text) {
        if (!text || text.trim() === '') {
            return {
                isValid: false,
                error: 'Text field is empty'
            };
        }
        
        return {
            isValid: true,
            error: null
        };
    },

    // QR Code validation
    validateQRInput(text) {
        if (!text || text.trim() === '') {
            return {
                isValid: false,
                error: 'QR Code Text field is empty'
            };
        }
        
        // Check if QRCode library is available
        if (typeof QRCode === "undefined") {
            return {
                isValid: false,
                error: 'QR Code library not loaded'
            };
        }
        
        return {
            isValid: true,
            error: null
        };
    },

    // Canvas object validation
    validateCanvasObject(object, allowedTypes = []) {
        if (!object) {
            return {
                isValid: false,
                error: 'No object selected'
            };
        }

        if (allowedTypes.length > 0 && !allowedTypes.includes(object.type)) {
            return {
                isValid: false,
                error: `Invalid object type. Expected: ${allowedTypes.join(', ')}, got: ${object.type}`
            };
        }

        return {
            isValid: true,
            error: null
        };
    },

    // Circle clip validation
    validateCircleClipTarget(activeObject) {
        if (!activeObject) {
            return {
                isValid: false,
                error: 'Bitte wählen Sie zuerst ein Element aus, um einen Kreis-Ausschnitt anzuwenden.',
                type: 'warning'
            };
        }

        if (activeObject === contentImage) {
            return {
                isValid: false,
                error: 'Kreis-Ausschnitt kann nicht auf das Hintergrundbild angewendet werden. Fügen Sie zuerst ein eigenes Bild über "Bild hinzufügen" ein.',
                type: 'warning'
            };
        }

        if (activeObject === logo || activeObject === logoName) {
            return {
                isValid: false,
                error: 'Kreis-Ausschnitt kann nicht auf das Logo angewendet werden. Wählen Sie ein eingefügtes Bild aus.',
                type: 'warning'
            };
        }

        const isValidForCircle = 
            activeObject.type === "image" ||
            activeObject.type === "rect" ||
            activeObject.type === "circle";

        if (!isValidForCircle) {
            return {
                isValid: false,
                error: 'Kreis-Ausschnitt kann nur auf eingefügte Bilder und Elemente angewendet werden. Wählen Sie zuerst ein Element aus.',
                type: 'warning'
            };
        }

        return {
            isValid: true,
            error: null
        };
    },

    // Download validation
    validateDownload() {
        const logoEnabled = LogoState.isLogoEnabled();

        // Only validate logo if logo feature is enabled
        if (logoEnabled && (!logoText || logoText === "")) {
            return {
                isValid: false,
                error: 'Wähle bitte ein Logo aus vor dem Download!'
            };
        }

        return {
            isValid: true,
            error: null
        };
    },

    // File size validation
    validateFileSize(file, maxSizeMB = 10) {
        if (!file) return { isValid: false, error: 'No file provided' };
        
        const maxSizeBytes = maxSizeMB * 1024 * 1024;
        
        if (file.size > maxSizeBytes) {
            return {
                isValid: false,
                error: `File too large. Maximum size is ${maxSizeMB}MB`
            };
        }
        
        return {
            isValid: true,
            error: null
        };
    }
};

// Make available globally
window.ValidationUtils = ValidationUtils;

// === resources/js/logo-state.js ===
/**
 * LogoState - Logo Enable/Disable State Management
 *
 * Manages the state of whether logos should be automatically added
 * to canvases. Logo is enabled by default and state does NOT persist across sessions.
 */

const LogoState = {
    // In-memory state - always starts as enabled
    _enabled: true,

    // Whether the region name on the logo bar is a transparent KNOCKOUT.
    // True is right on the plain green canvas: the letters show the green
    // behind them. Over a background photo it is wrong — the photo shows
    // through the letters and the name becomes unreadable. Then the name is
    // filled with the brand green instead, which matches the plain canvas and
    // stays legible over anything.
    _knockout: true,

    /**
     * Check if logo feature is enabled
     * @returns {boolean} True if logo should be added to canvas
     */
    isLogoEnabled() {
        return this._enabled;
    },

    /**
     * Set logo enabled state (session only, does not persist)
     * @param {boolean} enabled - True to enable logo, false to disable
     */
    setLogoEnabled(enabled) {
        this._enabled = Boolean(enabled);
    },

    /**
     * Whether the region name is knocked out of the white bar.
     * @returns {boolean}
     */
    isKnockoutEnabled() {
        return this._knockout;
    },

    /**
     * Set the knockout mode (session only, does not persist).
     * @param {boolean} enabled - True for a transparent name, false for green
     */
    setKnockoutEnabled(enabled) {
        this._knockout = Boolean(enabled);
    },

    /**
     * Initialize logo state - always starts enabled
     * Call this on page load
     */
    initialize() {
        // Always start with logo enabled
        this._enabled = true;
        this._knockout = true;
    }
};

// Make LogoState available globally
if (typeof window !== 'undefined') {
    window.LogoState = LogoState;
}

// Also export for Node.js testing
if (typeof global !== 'undefined') {
    global.LogoState = LogoState;
}


// === resources/js/alert-system.js ===
// Unified Alert System - DS v2.2 .gat-toast / .gat-toaster + inline .gat-callout
//
// - Toaster (top-fixed global container) -> .gat-toaster with .gat-toast children
// - Inline alert containers (e.g. #qr-alert-container) -> .gat-callout
//
// Legacy hooks preserved for tests and back-compat:
// - container still accessible via .app-alert-container selector
// - rendered alert nodes still carry the .alert class

const AlertSystem = {
    // Configuration
    config: {
        duration: 5000,
        fadeSpeed: 300,
        maxAlerts: 3
    },

    // Map legacy alert types to DS v2.2 .gat-toast--* variants
    // and DS v2.1 .gat-callout--* variants (for inline qr-alert container).
    alertTypes: {
        success: { toast: 'gat-toast--success', callout: 'gat-callout--success', icon: 'fas fa-check-circle' },
        warning: { toast: 'gat-toast--warn',    callout: 'gat-callout--warn',    icon: 'fas fa-exclamation-triangle' },
        warn:    { toast: 'gat-toast--warn',    callout: 'gat-callout--warn',    icon: 'fas fa-exclamation-triangle' },
        danger:  { toast: 'gat-toast--error',   callout: 'gat-callout--error',   icon: 'fas fa-exclamation-circle' },
        error:   { toast: 'gat-toast--error',   callout: 'gat-callout--error',   icon: 'fas fa-exclamation-circle' },
        info:    { toast: 'gat-toast--info',    callout: 'gat-callout--info',    icon: 'fas fa-info-circle' }
    },

    // Get the global toast region (.gat-toaster). Reuses the legacy
    // .app-alert-container element if it is in the DOM so existing
    // markup/tests keep working.
    getContainer() {
        let container = jQuery('.gat-toaster').first();
        if (container.length === 0) {
            const legacy = jQuery('.app-alert-container').first();
            if (legacy.length) {
                legacy.addClass('gat-toaster').removeClass('hidden');
                container = legacy;
            } else {
                container = jQuery('<div class="gat-toaster app-alert-container" role="region" aria-live="polite" aria-label="Benachrichtigungen"></div>');
                jQuery('body').append(container);
            }
        }
        return container;
    },

    // Show alert with enhanced styling
    show(message, type = 'info', options = {}) {
        const container = options.container ? jQuery(options.container) : this.getContainer();
        return this.showInContainer(message, type, container, options);
    },

    // Show alert in specific container.
    // - .gat-toaster region -> render as .gat-toast (fixed corner)
    // - any other container -> render as inline .gat-callout
    showInContainer(message, type = 'info', container, options = {}) {
        const alertConfig = this.alertTypes[type] || this.alertTypes['info'];

        if (container.length === 0) {
            console.warn('Alert container not found');
            return null;
        }

        const isToastRegion = container.hasClass('gat-toaster') || container.hasClass('app-alert-container');

        // Clear existing alerts if specified in options
        if (options.clearExisting) {
            container.empty();
        } else {
            // Limit number of alerts
            const existingAlerts = container.find('.alert');
            if (existingAlerts.length >= this.config.maxAlerts) {
                existingAlerts.first().remove();
            }
        }

        const alertHTML = isToastRegion
            ? `
                <div class="gat-toast ${alertConfig.toast} alert" role="alert">
                    <span class="gat-toast__icon" aria-hidden="true">
                        <i class="${alertConfig.icon}"></i>
                    </span>
                    <div class="gat-toast__body">${message}</div>
                    <button type="button" class="gat-toast__close alert-close-btn" aria-label="Schließen">
                        <span aria-hidden="true">&times;</span>
                    </button>
                </div>
            `
            : `
                <div class="gat-callout ${alertConfig.callout} alert" role="alert">
                    <div class="gat-callout__body">${message}</div>
                    <button type="button" class="gat-callout__close alert-close-btn" aria-label="Schließen">
                        <span aria-hidden="true">&times;</span>
                    </button>
                </div>
            `;

        container.removeClass('hidden').append(alertHTML);

        // Get the newly added alert
        const newAlert = container.find('.alert').last();

        // Add click handler for close button
        newAlert.find('.alert-close-btn').on('click', () => {
            this.closeAlertInContainer(newAlert, container);
        });

        // Auto-remove after configured duration
        if (options.autoClose !== false) {
            setTimeout(() => {
                this.closeAlertInContainer(newAlert, container);
            }, options.duration || this.config.duration);
        }

        // Scroll into view if specified
        if (options.scrollIntoView) {
            this.scrollAlertIntoView(container);
        }

        return newAlert;
    },

    // Close specific alert
    closeAlert(alertElement) {
        const container = this.getContainer();
        this.closeAlertInContainer(alertElement, container);
    },

    // Close specific alert in container
    closeAlertInContainer(alertElement, container) {
        alertElement.fadeOut(this.config.fadeSpeed, () => {
            alertElement.remove();

            // Hide container if no more alerts (only for inline containers;
            // .gat-toaster is fixed-positioned and harmless when empty)
            if (container.find('.alert').length === 0 && !container.hasClass('gat-toaster')) {
                container.addClass('hidden');
            }
        });
    },

    // Scroll alert into view - completely disabled
    scrollAlertIntoView(container) {
        // Auto-scroll removed completely
        return;
    },

    // Close all alerts
    closeAll() {
        const container = this.getContainer();
        container.find('.alert').fadeOut(this.config.fadeSpeed, function() {
            jQuery(this).remove();
        });
        if (!container.hasClass('gat-toaster')) {
            setTimeout(() => {
                container.addClass('hidden');
            }, this.config.fadeSpeed);
        }
    },

    // Specialized alert methods
    success(message, options = {}) {
        return this.show(message, 'success', options);
    },

    warning(message, options = {}) {
        return this.show(message, 'warning', options);
    },

    error(message, options = {}) {
        return this.show(message, 'error', options);
    },

    danger(message, options = {}) {
        return this.show(message, 'danger', options);
    },

    info(message, options = {}) {
        return this.show(message, 'info', options);
    },

    // QR-specific alert methods
    showQRAlert(message, type = 'info', options = {}) {
        const qrOptions = {
            container: '#qr-alert-container',
            clearExisting: true,
            scrollIntoView: true,
            ...options
        };

        // Show inline in QR container as .gat-callout
        const qrAlert = this.showInContainer(message, type, jQuery('#qr-alert-container'), qrOptions);

        // Also show in global toaster region for dual display
        const mainAlert = this.show(message, type, { autoClose: options.autoClose });

        return { qrAlert, mainAlert };
    },

    // Legacy support for existing code
    showTailwindAlert(message, type = 'info') {
        return this.show(message, type);
    }
};

// Global functions for backwards compatibility
function showAlert(message, type = 'danger') {
    return AlertSystem.show(message, type);
}

function showTailwindAlert(message, type = 'info') {
    return AlertSystem.show(message, type);
}

function showQRAlert(message, type = 'info') {
    return AlertSystem.showQRAlert(message, type);
}

// Make available globally
window.AlertSystem = AlertSystem;
window.showAlert = showAlert;
window.showTailwindAlert = showTailwindAlert;
window.showQRAlert = showQRAlert;


// === resources/js/canvas-utils.js ===
// Canvas Utilities - Centralized canvas manipulation functions

// Canvas scaling and positioning utilities
const CanvasUtils = {
    // Scale element to fit within specified ratios
    scaleElementToFit(element, maxWidthRatio = 0.5, maxHeightRatio = 0.4) {
        const maxWidth = canvas.width * maxWidthRatio;
        const maxHeight = canvas.height * maxHeightRatio;

        const elementWidth = element.width || element.getScaledWidth();
        const elementHeight = element.height || element.getScaledHeight();

        const widthScale = maxWidth / elementWidth;
        const heightScale = maxHeight / elementHeight;
        const scale = Math.min(widthScale, heightScale);

        if (element.type === "text") {
            if (widthScale < heightScale) {
                element.scaleToWidth(maxWidth);
            } else {
                element.scaleToHeight(maxHeight);
            }
        } else if (element.scaleToWidth && element.scaleToHeight) {
            if (widthScale < heightScale) {
                element.scaleToWidth(maxWidth);
            } else {
                element.scaleToHeight(maxHeight);
            }
        } else {
            element.scale(scale);
        }

        element.setCoords();
    },

    // Control visibility configurations
    disableScalingControls(object) {
        object.setControlsVisibility({
            mt: false,
            mb: false,
            ml: false,
            mr: false,
            bl: false,
            br: false,
            tl: false,
            tr: false,
            mtr: false,
        });
    },

    relativeScalingControlsOnly(object) {
        object.setControlsVisibility({
            mt: false,
            mb: false,
            ml: false,
            mr: false,
            bl: true,
            br: true,
            tl: true,
            tr: true,
            mtr: true,
        });
    },

    // Canvas snapping functionality
    enableSnap(canvasInstance, snapZone = null) {
        console.log('[CanvasUtils.enableSnap] Initializing snap with canvas:', canvasInstance ? 'defined' : 'undefined');

        if (!snapZone) {
            snapZone = canvasInstance.width / AppConstants.CANVAS.SNAP_ZONE_RATIO;
        }

        console.log('[CanvasUtils.enableSnap] Snap zone calculated:', snapZone);

        canvasInstance.on("object:moving", function (options) {
            const target = options.target;

            // Skip if not eligible for snapping
            if (target === contentImage || target === logo || target === logoName) {
                return;
            }

            // Safety check for getCenterPoint method
            if (!target || typeof target.getCenterPoint !== 'function') {
                return;
            }

            const objectCenter = target.getCenterPoint();
            const canvasCenter = canvasInstance.width / 2;
            const distanceFromCenter = Math.abs(objectCenter.x - canvasCenter);

            if (distanceFromCenter < snapZone) {
                // Store center point before adjustment
                const centerBefore = target.getCenterPoint();

                // Calculate horizontal adjustment needed to center
                const deltaX = canvasCenter - centerBefore.x;

                // Apply adjustment while preserving vertical position
                target.set({
                    left: target.left + deltaX
                });
                target.setCoords();

                // Verify center after adjustment
                const centerAfter = target.getCenterPoint();

                console.log(
                    '%c[SNAP] CENTER SNAP',
                    'background: #257639; color: white; font-weight: bold; padding: 2px 6px;',
                    '\n  Object type:', target.type,
                    '\n  Center before:', `(${centerBefore.x.toFixed(2)}, ${centerBefore.y.toFixed(2)})`,
                    '\n  Center after:', `(${centerAfter.x.toFixed(2)}, ${centerAfter.y.toFixed(2)})`,
                    '\n  Canvas center:', canvasCenter.toFixed(2),
                    '\n  Adjustment:', deltaX.toFixed(2) + 'px',
                    '\n  Snap zone:', snapZone.toFixed(2) + 'px'
                );
            }
        });
    },

    // Rotation snapping functionality - snaps in real-time during rotation
    enableRotationSnap(canvasInstance, tolerance = null) {
        console.log('[CanvasUtils.enableRotationSnap] Initializing rotation snap with canvas:', canvasInstance ? 'defined' : 'undefined');

        if (!tolerance) {
            tolerance = AppConstants.CANVAS.ROTATION_SNAP_TOLERANCE;
        }

        const snapAngles = AppConstants.CANVAS.ROTATION_SNAP_ANGLES;
        console.log('[CanvasUtils.enableRotationSnap] Tolerance:', tolerance, 'Snap angles:', snapAngles);

        // Use object:rotating for real-time snapping while mouse is down
        canvasInstance.on("object:rotating", function (e) {
            const target = e.target;

            if (!target) {
                return;
            }

            // Exclude protected objects from rotation snapping
            if (target === contentImage || target === logo || target === logoName) {
                return;
            }

            // Safety check for getCenterPoint method
            if (typeof target.getCenterPoint !== 'function') {
                return;
            }

            // Normalize angle to 0-360 range
            let currentAngle = target.angle % 360;
            if (currentAngle < 0) {
                currentAngle += 360;
            }

            // Find closest snap angle
            let closestAngle = null;
            let minDifference = Infinity;

            for (const snapAngle of snapAngles) {
                // Calculate difference considering angle wrapping
                let difference = Math.abs(currentAngle - snapAngle);

                // Handle wrap-around (e.g., 359° to 0°)
                if (difference > 180) {
                    difference = 360 - difference;
                }

                if (difference < minDifference) {
                    minDifference = difference;
                    closestAngle = snapAngle;
                }
            }

            // Apply snap if within tolerance
            if (closestAngle !== null && minDifference <= tolerance) {
                // Store visual center point BEFORE rotation change
                const centerBefore = target.getCenterPoint();

                // Apply rotation snap
                target.set({ angle: closestAngle });

                // Get visual center point AFTER rotation change
                const centerAfter = target.getCenterPoint();

                // Calculate position adjustment to restore visual center
                const deltaX = centerBefore.x - centerAfter.x;
                const deltaY = centerBefore.y - centerAfter.y;

                // Restore original visual position
                target.set({
                    left: target.left + deltaX,
                    top: target.top + deltaY
                });

                target.setCoords();

                // Only log once per snap (reduce console spam)
                if (!target._isSnapped || target._snappedTo !== closestAngle) {
                    console.log(
                        '%c[SNAP] ROTATION SNAP',
                        'background: #e10078; color: white; font-weight: bold; padding: 2px 6px;',
                        '\n  Object type:', target.type,
                        '\n  Original angle:', currentAngle.toFixed(2) + '°',
                        '\n  Snapped to:', closestAngle + '°',
                        '\n  Difference:', minDifference.toFixed(2) + '°',
                        '\n  Tolerance:', tolerance + '°',
                        '\n  Center before:', `(${centerBefore.x.toFixed(2)}, ${centerBefore.y.toFixed(2)})`,
                        '\n  Center after:', `(${centerAfter.x.toFixed(2)}, ${centerAfter.y.toFixed(2)})`,
                        '\n  Position adjustment:', `(${deltaX.toFixed(2)}, ${deltaY.toFixed(2)})`
                    );
                }
                target._isSnapped = true;
                target._snappedTo = closestAngle;
            } else {
                // Clear snap state when outside tolerance
                target._isSnapped = false;
                target._snappedTo = null;
            }
        });
    },

    // Picture movement constraints
    //
    // The background is cover-scaled (see positionBackgroundImage), so it always
    // covers the content rect on both axes and overflows on the longer one. As
    // the user pans the image we clamp it so the content rect stays fully
    // covered — the image edge can never move inside the rect (which would
    // expose the green background). We clamp against the ACTUAL scaled size
    // rather than re-deriving a single-axis fit, so the logic is correct for
    // any aspect ratio.
    enablePictureMove(canvasInstance) {
        canvasInstance.on("object:moving", function (options) {
            if (options.target === contentImage) {
                const scaledWidth = options.target.getScaledWidth();
                const scaledHeight = options.target.getScaledHeight();

                // Allowed range for the image's top-left so the rect stays
                // covered: max edge flush at rect start, min edge flush at end.
                const maxLeft = contentRect.left;
                const minLeft = contentRect.left + contentRect.width - scaledWidth;
                const maxTop = contentRect.top;
                const minTop = contentRect.top + contentRect.height - scaledHeight;

                let left = options.target.left;
                let top = options.target.top;

                if (left > maxLeft) left = maxLeft;
                if (left < minLeft) left = minLeft;
                if (top > maxTop) top = maxTop;
                if (top < minTop) top = minTop;

                if (left !== options.target.left || top !== options.target.top) {
                    options.target.set({ left, top }).setCoords();
                }
            }
        });
    },

    // Background image positioning
    /**
     * Where the background photo is anchored when it overflows the frame.
     * 0.5/0.5 is the centre — what the app has always done. 0 shows the left
     * or top edge, 1 the right or bottom.
     *
     * The photo is cover-scaled, so one axis almost always overflows and
     * something gets cropped. Centring is a guess: a portrait in a landscape
     * template loses the top of the head, a group photo loses the people at
     * the edges. A person can drag the image to fix that (the overflowing
     * axis is left unlocked below); this is the same choice for callers who
     * cannot drag.
     */
    backgroundFocus: { x: 0.5, y: 0.5 },

    setBackgroundFocus(x, y) {
        const clamp = function (v, fallback) {
            return typeof v === "number" && v >= 0 && v <= 1 ? v : fallback;
        };
        this.backgroundFocus = {
            x: clamp(x, this.backgroundFocus.x),
            y: clamp(y, this.backgroundFocus.y),
        };
    },

    positionBackgroundImage() {
        if (contentImage != null) {
            canvas.remove(contentRect);
            canvas.remove(contentImage);
            
            contentImage.selectable = true;
            this.disableScalingControls(contentImage);

            const clipRect = new fabric.Rect({
                left: contentRect.left,
                top: contentRect.top,
                width: contentRect.width,
                height: contentRect.height,
                absolutePositioned: true,
            });

            // Cover-scale: pick the larger of the two fit ratios so the image
            // always fully covers the content rect on BOTH axes. The clipPath
            // crops whatever overflows. This guarantees no background gap
            // (green border) for any image/canvas aspect-ratio combination.
            const coverScale = Math.max(
                contentRect.width / contentImage.width,
                contentRect.height / contentImage.height
            );
            contentImage.scale(coverScale);

            // Lock the axis that fits exactly; leave the overflowing axis free
            // so the user can still pan the image to reframe it. When the
            // image covers exactly (same aspect) both axes lock.
            const scaledWidth = contentImage.getScaledWidth();
            const scaledHeight = contentImage.getScaledHeight();
            const widthOverflow = scaledWidth - contentRect.width;
            const heightOverflow = scaledHeight - contentRect.height;
            const EPS = 0.5; // sub-pixel tolerance
            contentImage.lockMovementX = widthOverflow <= EPS;
            contentImage.lockMovementY = heightOverflow <= EPS;

            contentImage.clipPath = clipRect;
            canvas.add(contentImage);
            canvas.sendToBack(contentImage);
            // Anchor the image over the CONTENT RECT (not the whole canvas, so
            // bordered templates stay correct). The overflow is distributed
            // according to backgroundFocus: 0.5 splits it evenly, which is the
            // long-standing centred behaviour; 0 pins the left/top edge, 1 the
            // right/bottom. Either way the rect stays fully covered.
            const focus = this.backgroundFocus;
            contentImage.set({
                left: contentRect.left - (scaledWidth - contentRect.width) * focus.x,
                top: contentRect.top - (scaledHeight - contentRect.height) * focus.y,
            });
            contentImage.setCoords();
        }
    },

    // Logo management
    bringLogoToFront() {
        if (logo) canvas.bringToFront(logo);
        if (logoName) canvas.bringToFront(logoName);
    },

    // Circle clipping utility
    applyCircleClip(activeObject, sizePercentage = 0.7) {
        if (!activeObject) return false;

        const isValidForCircle = 
            activeObject &&
            activeObject !== contentImage &&
            activeObject !== contentRect &&
            activeObject !== logo &&
            activeObject !== logoName &&
            (activeObject.type === "image" ||
             activeObject.type === "rect" ||
             activeObject.type === "circle");

        if (!isValidForCircle) return false;

        const originalWidth = activeObject.width;
        const originalHeight = activeObject.height;
        const smallestOriginalDimension = Math.min(originalHeight, originalWidth);
        const radius = (smallestOriginalDimension * sizePercentage) / 2;

        if (activeObject.clipPath) {
            activeObject.clipPath = null;
        } else {
            const clipPath = new fabric.Circle({
                radius: radius,
                left: 0,
                top: 0,
                originX: "center",
                originY: "center",
            });
            activeObject.clipPath = clipPath;
        }

        canvas.renderAll();
        return true;
    },

    // Canvas export with DPI handling
    async exportCanvas(format, quality, targetDPI = 200) {
        const screenDPI = 72;
        const maxPixels = 250000000;

        // Make the web fonts canvas-available BEFORE re-measuring/rendering.
        // The 2D canvas only uses a loaded web font after an explicit
        // document.fonts.load() for that exact weight/style — document.fonts.ready
        // and .check() are NOT sufficient. Awaiting the load here makes the
        // export deterministic regardless of how late the font finished loading
        // relative to text being added (fixed fallback glyphs in headless
        // reference runs and guarantees real downloads use Gotham Narrow too).
        if (typeof document !== "undefined" && document.fonts && document.fonts.load) {
            try {
                const fontSpecs = (typeof AppConstants !== "undefined" &&
                    AppConstants.FONTS && AppConstants.FONTS.PRELOAD_FONTS)
                    ? AppConstants.FONTS.PRELOAD_FONTS.map(function (f) {
                        const style = f.style && f.style !== "normal" ? f.style + " " : "";
                        return style + (f.weight || 400) + ' 16px "' + f.family + '"';
                    })
                    : [];
                await Promise.all(fontSpecs.map(function (spec) {
                    return document.fonts.load(spec).catch(function () {});
                }));
            } catch (e) {
                // Non-fatal: fall through to render with whatever is available.
            }
        }

        // Re-measure text with the now-loaded fonts before exporting.
        // Fabric caches a text object's char metrics at creation time; if a
        // web font (Gotham Narrow) finished loading AFTER the text was added, the
        // cached fallback metrics — and thus the exported PNG — stick unless we
        // force a re-measure. This makes the export deterministic regardless of
        // font-load timing (fixes fallback glyphs in headless reference runs).
        canvas.getObjects().forEach(function (obj) {
            if (obj && (obj.type === "text" || obj.type === "i-text" || obj.type === "textbox")) {
                obj.dirty = true;
                if (typeof obj.initDimensions === "function") obj.initDimensions();
                if (typeof obj.setCoords === "function") obj.setCoords();
            }
        });
        canvas.renderAll();

        const baseMultiplier = targetDPI / screenDPI;
        const finalWidth = canvas.width * baseMultiplier;
        const finalHeight = canvas.height * baseMultiplier;
        const totalPixels = finalWidth * finalHeight;

        let actualMultiplier = baseMultiplier;
        let actualDPI = targetDPI;

        if (totalPixels > maxPixels) {
            actualMultiplier = Math.sqrt(maxPixels / (canvas.width * canvas.height));
            actualDPI = Math.round(actualMultiplier * screenDPI);
            console.warn(`Canvas too large for ${targetDPI} DPI. Reduced to ${actualDPI} DPI`);
        }

        try {
            const dataURL = canvas.toDataURL({
                format: format,
                quality: quality,
                multiplier: actualMultiplier,
            });

            if (dataURL === "data:,") {
                throw new Error("Canvas export failed - empty result");
            }

            return { dataURL, actualDPI, targetDPI };
        } catch (error) {
            console.error("Canvas export error:", error);
            throw error;
        }
    }
};

// Make available globally
window.CanvasUtils = CanvasUtils;

// === resources/js/event-handlers.js ===
// Event Handler Utilities - Centralized event handling patterns

const EventHandlerUtils = {
    // Generic event binding utility
    bindHandler(selector, event, handler) {
        jQuery(selector).off(event).on(event, handler);
    },

    // Batch event binding
    bindHandlers(handlerMap) {
        Object.keys(handlerMap).forEach(selector => {
            const handlers = handlerMap[selector];
            Object.keys(handlers).forEach(event => {
                this.bindHandler(selector, event, handlers[event]);
            });
        });
    },

    // Canvas object handlers
    setupCanvasObjectHandlers() {
        const handlers = {
            '#text': {
                'input': function() {
                    setValue("text", jQuery(this).val());
                }
            },
            '#scale': {
                'input': function() {
                    const activeObject = canvas.getActiveObject();
                    if (activeObject && activeObject !== contentImage) {
                        activeObject.scale(parseFloat(this.value)).setCoords();
                        canvas.renderAll();
                        updateScale(activeObject);
                    }
                }
            },
            '#text-color': {
                'change': function() {
                    const activeObject = canvas.getActiveObject();
                    if (activeObject && activeObject.get('type') === "text") {
                        setValue("fill", jQuery(this).find(":selected").attr('value'));
                    }
                }
            },
            'input[name="align"]': {
                'change': function() {
                    const alignValue = jQuery(this).attr('id');
                    setValue("textAlign", alignValue);
                    jQuery(this).parent().trigger('update-status');
                }
            },
            '#stroke-width': {
                'input': function() {
                    const width = jQuery(this).val();
                    setValue("strokeWidth", width == 0 ? null : width);
                }
            },
            '#shadow-depth': {
                'input': function() {
                    setValue("shadow", createShadow('black', jQuery(this).val()));
                }
            },
            '#line-height': {
                'change': function() {
                    const activeObject = canvas.getActiveObject();
                    if (activeObject && activeObject.get('type') === "text") {
                        const lineHeight = parseFloat(jQuery(this).val());
                        setValue("lineHeight", lineHeight);
                    }
                }
            },
            '#font-style-select': {
                'change': function() {
                    const activeObject = canvas.getActiveObject();
                    if (activeObject && activeObject.get('type') === "text") {
                        const optId = jQuery(this).val();
                        const opt = AppConstants.FONTS.OPTIONS.find(o => o.id === optId)
                            || AppConstants.FONTS.OPTIONS[0];
                        // Set weight/style before the family swap so the
                        // FontFaceObserver-gated re-render uses them.
                        activeObject.set("fontWeight", opt.weight);
                        activeObject.set("fontStyle", opt.style);
                        loadFont(opt.family);
                    }
                }
            }
        };

        this.bindHandlers(handlers);
    },

    // Main application handlers
    setupMainAppHandlers() {
        const handlers = {
            '#canvas-template': {
                'change': function() {
                    replaceCanvas();
                    if (typeof updateCanvasDimensions === "function") {
                        setTimeout(() => {
                            updateCanvasDimensions();
                        }, 100);
                    }
                }
            },
            '#logo-selection': {
                'change': function() {
                    // Only add logo if feature is enabled
                    if (LogoState.isLogoEnabled()) {
                        addLogo();
                    }
                }
            },
            '#scale-direction': {
                'change': function() {
                    CanvasUtils.positionBackgroundImage();
                }
            },
            '#remove-element': {
                'click': function() {
                    const activeObject = canvas.getActiveObject();
                    if (activeObject && 
                        activeObject !== contentImage && 
                        activeObject !== logo) {
                        canvas.remove(activeObject);
                    }
                }
            },
            '#bring-to-front': {
                'click': function() {
                    const activeObject = canvas.getActiveObject();
                    if (activeObject && 
                        activeObject !== contentImage && 
                        activeObject !== contentRect) {
                        canvas.bringToFront(activeObject);
                        CanvasUtils.bringLogoToFront();
                        canvas.renderAll();
                    }
                }
            }
        };

        this.bindHandlers(handlers);
    },

    // Text creation handler
    setupTextHandler() {
        this.bindHandler('#add-text', 'click', function() {
            const textValidation = ValidationUtils.validateTextInput(jQuery("#text").val());
            
            if (!textValidation.isValid) {
                showAlert("Error! " + textValidation.error);
                return;
            }

            const initialFontSize = canvas.width / 2;
            const optId = jQuery('#font-style-select').val();
            const opt = AppConstants.FONTS.OPTIONS.find(o => o.id === optId)
                || AppConstants.FONTS.OPTIONS[0];
            const selectedFont = opt.family;

            const text = new fabric.Text(jQuery("#text").val(), {
                fontFamily: selectedFont,
                fontSize: initialFontSize,
                fontWeight: opt.weight,
                charSpacing: AppConstants.FONTS.CHAR_SPACING,
                fontStyle: opt.style,
                textAlign: jQuery('input[name="align"]:checked').val(),
                fill: jQuery("#text-color").find(":selected").attr("value"),
                stroke: "#000000",
                strokeWidth: 0,
                shadow: createShadow("#000000", jQuery("#shadow-depth").val()),
                objectCaching: false,
                lineHeight: parseFloat(jQuery("#line-height").val()) || 1.0,
                centeredScaling: false,
                selectable: true,
                moveable: true,
                hasControls: true,
                hasBorders: true,
                perPixelTargetFind: true,
            });

            canvas.add(text);
            CanvasUtils.relativeScalingControlsOnly(text);
            CanvasUtils.scaleElementToFit(text, 0.8, 0.5);
            canvas.centerObject(text);
            text.set({
                top: canvas.height / 2 - text.getScaledHeight() / 2,
            });

            text.setCoords();
            canvas.setActiveObject(text);
            updateScale(text);
            // Keep the organisation logo on top. Without this a headline
            // placed near the bottom covers it, which the other add handlers
            // already guard against.
            CanvasUtils.bringLogoToFront();
            canvas.renderAll();
        });
    },

    // Image upload handler
    setupImageUploadHandler() {
        this.bindHandler('#add-image', 'input', function() {
            const file = this.files[0];
            if (!file) return;

            const fileValidation = ValidationUtils.isValidImageFile(file);
            jQuery("#add-image").val("");

            if (!fileValidation) {
                showAlert("Error! Invalid Image");
                return;
            }

            const reader = new FileReader();
            reader.onload = function() {
                const image = new Image();
                image.src = reader.result;
                image.onload = function() {
                    fabric.Image.fromURL(reader.result, function(fabricImage) {
                        CanvasUtils.scaleElementToFit(fabricImage, 0.5, 0.4);
                        CanvasUtils.relativeScalingControlsOnly(fabricImage);
                        canvas.add(fabricImage).setActiveObject(fabricImage);
                        canvas.centerObject(fabricImage);
                        updateScale(fabricImage);
                        CanvasUtils.bringLogoToFront();
                    }, {
                        opacity: jQuery("#opacity").val(),
                    });
                };
            };
            reader.readAsDataURL(file);
        });
    },

    // Circle clip handler
    setupCircleClipHandler() {
        this.bindHandler('#add-circle', 'click', function() {
            const activeObject = canvas.getActiveObject();
            const sizeString = jQuery("#circle-radius").val();
            const size = parseInt(sizeString) || 2;

            const validation = ValidationUtils.validateCircleClipTarget(activeObject);
            
            if (!validation.isValid) {
                showAlert(validation.error, validation.type || 'warning');
                return;
            }

            // Map size values to percentages
            const sizePercentageMap = {
                2: 0.9, // Groß - 90%
                3: 0.7, // Mittel - 70%
                4: 0.5  // Klein - 50%
            };
            
            const sizePercentage = sizePercentageMap[size] || 0.7;
            CanvasUtils.applyCircleClip(activeObject, sizePercentage);
        });
    },

    // Pink circle handler
    setupPinkCircleHandler() {
        this.bindHandler('#add-pink-circle', 'click', function() {
            const radius = contentRect.width / 4;
            const pinkCircle = new fabric.Circle({
                top: contentRect.height / 3,
                left: contentRect.width / 3,
                radius: radius,
                fill: "rgb(225,0,120)",
            });
            
            CanvasUtils.scaleElementToFit(pinkCircle, 0.3, 0.3);
            CanvasUtils.relativeScalingControlsOnly(pinkCircle);
            canvas.add(pinkCircle);
            
            // Bring text objects to front
            canvas.getObjects().forEach(object => {
                if (object.get("type") === "text") {
                    canvas.bringToFront(object);
                }
            });

            // ...and the organisation logo above those.
            CanvasUtils.bringLogoToFront();
            canvas.renderAll();
        });
    },

    // Green panel handler.
    //
    // The brand guide requires type to sit on a green surface. Without a
    // photo the whole canvas already is one, so this is only needed over a
    // background image — but there it is not optional: white text laid
    // straight over a photograph breaks the rule, however legible it looks.
    setupPanelHandler() {
        this.bindHandler('#add-panel', 'click', function() {
            const panel = new fabric.Rect({
                width: contentRect.width * 0.8,
                height: contentRect.height * 0.28,
                fill: AppConstants.COLORS.BACKGROUND_SECONDARY,
                objectCaching: false,
            });

            CanvasUtils.relativeScalingControlsOnly(panel);
            canvas.add(panel);
            canvas.centerObject(panel);

            // Behind every text already on the canvas — a panel added after a
            // headline is meant to go under it, not over it.
            canvas.getObjects().forEach(function (object) {
                if (object.get("type") === "text") {
                    canvas.bringToFront(object);
                }
            });
            CanvasUtils.bringLogoToFront();

            canvas.setActiveObject(panel);
            updateScale(panel);
            canvas.renderAll();
        });
    },

    // Cross/check mark handler
    setupCrossHandler() {
        this.bindHandler('#add-cross', 'click', function() {
            fabric.Image.fromURL(
                generatorApplicationURL + "resources/images/Wahlkreuz.png",
                function(image) {
                    CanvasUtils.scaleElementToFit(image, 0.4, 0.3);
                    canvas.add(image);
                    canvas.centerObject(image);
                    canvas.bringToFront(image);
                    // The Wahlkreuz is brought to the very front above, which
                    // would otherwise put it over the organisation logo.
                    CanvasUtils.bringLogoToFront();
                }
            );
        });
    },

    // QR Code handler
    setupQRCodeHandler() {
        this.bindHandler('#add-qr-code', 'click', function() {
            const qrText = jQuery("#qr-text").val().trim();
            const validation = ValidationUtils.validateQRInput(qrText);
            
            if (!validation.isValid) {
                showAlert("Error! " + validation.error);
                return;
            }

            const tempDiv = document.createElement("div");
            tempDiv.style.display = "none";
            document.body.appendChild(tempDiv);

            try {
                const targetQRSize = Math.max(512, Math.min(2048, Math.floor(canvas.width / 4)));
                const qrColor = jQuery("#qr-color").val() || "#000000";
                
                const qr = new QRCode(tempDiv, {
                    text: qrText,
                    width: targetQRSize,
                    height: targetQRSize,
                    colorDark: qrColor,
                    colorLight: "#ffffff",
                    correctLevel: QRCode.CorrectLevel.M,
                });

                setTimeout(function() {
                    const qrImg = tempDiv.querySelector("img");
                    if (qrImg) {
                        const borderPercent = 0.05;
                        const borderSize = Math.floor(targetQRSize * borderPercent);
                        const totalSize = targetQRSize + borderSize * 2;

                        const tempCanvas = document.createElement("canvas");
                        tempCanvas.width = totalSize;
                        tempCanvas.height = totalSize;
                        const ctx = tempCanvas.getContext("2d");

                        ctx.fillStyle = "#ffffff";
                        ctx.fillRect(0, 0, totalSize, totalSize);
                        ctx.drawImage(qrImg, borderSize, borderSize, targetQRSize, targetQRSize);

                        fabric.Image.fromURL(tempCanvas.toDataURL(), function(qrImage) {
                            CanvasUtils.scaleElementToFit(qrImage, 0.25, 0.25);
                            CanvasUtils.relativeScalingControlsOnly(qrImage);
                            canvas.add(qrImage).setActiveObject(qrImage);
                            canvas.centerObject(qrImage);
                            updateScale(qrImage);
                            CanvasUtils.bringLogoToFront();
                            document.body.removeChild(tempDiv);
                        });
                    } else {
                        showAlert("Error generating QR Code image");
                        document.body.removeChild(tempDiv);
                    }
                }, 100);
            } catch (error) {
                showAlert("Error generating QR Code: " + error.message);
                document.body.removeChild(tempDiv);
            }
        });
    },

    // Download handler
    setupDownloadHandler() {
        this.bindHandler('#generate-meme', 'click', async function() {
            const validation = ValidationUtils.validateDownload();

            if (!validation.isValid) {
                alert(validation.error);
                return;
            }

            if (confirm("Hast du das Copyright bei Fotos überprüft und angegeben und das Impressum wo notwendig hinzugefügt?")) {
                const currentTemplate = template_values[template];
                const targetDPI = currentTemplate.dpi || 200;
                const format = jQuery("#image-format").find(":selected").attr("value");
                const quality = parseFloat(jQuery("#image-quality").find(":selected").attr("value"));

                try {
                    const exportResult = await CanvasUtils.exportCanvas(format, quality, targetDPI);

                    const link = document.createElement("a");
                    link.href = exportResult.dataURL;
                    link.download = createImgName();
                    link.click();

                    if (exportResult.actualDPI < exportResult.targetDPI) {
                        alert(`Download erfolgreich mit ${exportResult.actualDPI} DPI (reduziert von ${exportResult.targetDPI} DPI für Kompatibilität)`);
                    }
                } catch (error) {
                    alert("Fehler beim Erstellen des Bildes. Das Format ist möglicherweise zu groß für diesen Browser.");
                }
            }
        });
    },

    // Knockout toggle: transparent region name versus a green one.
    setupLogoKnockoutHandler() {
        this.bindHandler('#logo-knockout-toggle', 'change', function() {
            LogoState.setKnockoutEnabled(jQuery(this).is(':checked'));
            if (LogoState.isLogoEnabled()) {
                addLogo();
            }
        });
    },

    // Logo toggle handler
    setupLogoToggleHandler() {
        this.bindHandler('#logo-toggle', 'change', function() {
            const isChecked = jQuery(this).is(':checked');
            LogoState.setLogoEnabled(isChecked);

            if (isChecked) {
                // Re-add logo
                addLogo();

                // Re-enable logo selection dropdown
                jQuery('#logo-selection').prop('disabled', false).removeClass('opacity-50');
            } else {
                // Remove logo from canvas
                if (logo != null) {
                    canvas.remove(logo);
                    canvas.remove(logoName);
                    logo = null;
                    logoName = null;
                    canvas.renderAll();
                }

                // Disable logo selection dropdown
                jQuery('#logo-selection').prop('disabled', true).addClass('opacity-50');
            }
        });
    },

    // Initialize all handlers
    initializeAllHandlers() {
        this.setupCanvasObjectHandlers();
        this.setupMainAppHandlers();
        this.setupTextHandler();
        this.setupImageUploadHandler();
        this.setupCircleClipHandler();
        this.setupPinkCircleHandler();
        this.setupCrossHandler();
        this.setupPanelHandler();
        this.setupQRCodeHandler();
        this.setupDownloadHandler();
        this.setupLogoToggleHandler();
        this.setupLogoKnockoutHandler();
    }
};

