// === resources/js/choice-image.js ===
jQuery(function () {
    // Event: Choice meme from gallery
    jQuery('.app-memes-container').delegate('img', 'click', function () {
        var $img = jQuery(this);
        var imgInfo = {
            url: $img.attr('src'),
            height: $img.attr('img-height'),
            width: $img.attr('img-width'),
        };
        processMeme(imgInfo);
    });

    // Read a File object, validate it as an image, and feed it through processMeme.
    // Shared between the <input type="file"> change handler and drag-and-drop on
    // the .gat-dropzone label.
    function loadMemeFile(file) {
        if (!file) return;

        if (!ValidationUtils.isValidImageFile(file)) {
            showAlert('Error! Invalid Image');
            return;
        }

        const reader = new FileReader();
        reader.onload = function () {
            var meme = new Image();
            meme.onload = function () {
                processMeme({
                    url: reader.result,
                    height: meme.height,
                    width: meme.width,
                });
            };
            meme.onerror = function () {
                showAlert('Error loading image');
            };
            meme.src = reader.result;
        };
        reader.onerror = function () {
            showAlert('Error reading file');
        };
        reader.readAsDataURL(file);
    }

    // Event: Upload local image via file input
    jQuery('#meme-input').on('change', function () {
        const file = this.files[0];
        jQuery('#meme-input').val(''); // Reset file input
        loadMemeFile(file);
    });

    // Drag-and-drop on the .gat-dropzone label. The label already forwards
    // clicks to #meme-input (native for=…); we add drag-over visual feedback
    // and dropped-file handling on top.
    const dropzone = document.getElementById('meme-dropzone');
    if (dropzone) {
        ['dragenter', 'dragover'].forEach(function (evt) {
            dropzone.addEventListener(evt, function (e) {
                e.preventDefault();
                e.stopPropagation();
                dropzone.classList.add('is-dragover');
            });
        });
        ['dragleave', 'dragend', 'drop'].forEach(function (evt) {
            dropzone.addEventListener(evt, function (e) {
                e.preventDefault();
                e.stopPropagation();
                dropzone.classList.remove('is-dragover');
            });
        });
        dropzone.addEventListener('drop', function (e) {
            const file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
            loadMemeFile(file);
        });
    }
});


// === resources/js/handlers.js ===
// Font management
function loadFont(font) {
    const customFonts = ['Gotham Narrow', 'Vollkorn'];
    const text = canvas.getActiveObject();
    
    if (!text) return;
    
    if (customFonts.includes(font)) {
        const fontObserver = new FontFaceObserver(font);
        fontObserver.load().then(function () {
            text.set("fontFamily", "");
            text.set("fontFamily", font);
            canvas.renderAll();
        });
    } else {
        text.set("fontFamily", font);
        canvas.renderAll();
    }
}

// UI state management
function updateInputs() {
    const activeObject = canvas.getActiveObject();

    if (activeObject && activeObject.get('type') === "text") {
        enableTextMethods();
        jQuery('#text').val(activeObject.text);
        jQuery('#text-color').val(activeObject.fill);
        jQuery('#line-height').val(activeObject.lineHeight);
        jQuery(`input[value="${activeObject.textAlign}"]`).parent().trigger('update-status');
        updateScale(activeObject);
    }
}

function updateScale(activeObject) {
    const scale = Number(parseFloat(activeObject.scaleX)).toFixed(2);
    jQuery('#scale').val(scale);
}

// Event handler utility - using centralized EventHandlerUtils
function bindHandler(selector, event, handler) {
    return EventHandlerUtils.bindHandler(selector, event, handler);
}

// Section toggle functionality
function toggleSection(sectionId) {
    const section = document.getElementById(sectionId);
    const chevron = document.getElementById(sectionId + '-chevron');
    const button = document.querySelector(`[onclick="toggleSection('${sectionId}')"]`);
    
    if (section.style.display === 'none' || section.classList.contains('hidden')) {
        // Show section
        section.style.display = 'block';
        section.classList.remove('hidden');
        chevron.style.transform = 'rotate(0deg)';
        button.setAttribute('aria-expanded', 'true');
    } else {
        // Hide section
        section.style.display = 'none';
        section.classList.add('hidden');
        chevron.style.transform = 'rotate(-90deg)';
        button.setAttribute('aria-expanded', 'false');
    }
}

// Canvas object event handlers - now managed by EventHandlerUtils
function loadObjectHandlers() {
    EventHandlerUtils.setupCanvasObjectHandlers();
}

